const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
const repos = (items[0].json.repos || 'owner/repo').split(',');
const results = [];
for (const repo of repos) {
  const [owner, repoName] = repo.trim().split('/');
  results.push({
    owner,
    repo: repoName,
    since: weekAgo
  });
}
return results;

const commits = $input.all();
const prs = $("GitHub PRs").all();
const issues = $("GitHub Issues").all();

const summary = {
  repo: commits[0].json.owner + '/' + commits[0].json.repo,
  week_start: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
  week_end: new Date().toISOString().split('T')[0],
  total_commits: commits.length,
  total_prs_merged: prs.filter(p => p.json.merged_at).length,
  total_issues_closed: issues.length,
  authors: [...new Set(commits.map(c => c.json.commit?.author?.name || 'Unknown'))],
  commit_messages: commits.map(c => `- ${c.json.commit?.message?.split('\n')[0] || ''}`).join('\n'),
  pr_summary: prs.filter(p => p.json.merged_at).map(p => `- #${p.json.number} ${p.json.title}`).join('\n'),
  raw_commits: JSON.stringify(commits.map(c => ({
    message: c.json.commit?.message?.split('\n')[0],
    author: c.json.commit?.author?.name,
    date: c.json.commit?.author?.date,
    url: c.json.html_url
  }))),
  raw_prs: JSON.stringify(prs.filter(p => p.json.merged_at).map(p => ({
    title: p.json.title,
    number: p.json.number,
    url: p.json.html_url,
    merged: p.json.merged_at
  })))
};
return [summary];

